fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    // We assume `list` is non‐empty as per the problem statement.
    // Compute the effective rotation mod the length:
    let k = n % len;
    // If k == 0, the rotation is a no‐op—just return a clone of the original.
    if k == 0 {
        return list.clone();
    }
    // The split point: how many items to move from the back to the front.
    let s = len - k;
    // Build a new Vec with exactly the right capacity.
    let mut new_list = Vec::with_capacity(len);
    // First take the suffix from s..len
    new_list.extend_from_slice(&list[s..]);
    // Then take the prefix from 0..s
    new_list.extend_from_slice(&list[..s]);
    new_list
}

